func TestParseHeader(t *testing.T) {
	for i, s := range even {
		h, err := ParseHeader(s)
		if err != nil {
			t.Fatalf("chunk %d: %v", i, err)
		}
		want := Header{Version: 1, ChunkSetID: 0x2dcf2, TotalChunks: 6, ChunkIndex: i}
		if h != want {
			t.Errorf("chunk %d: got %+v, want %+v", i, h, want)
		}
	}
	if _, err := ParseHeader("md1yqpqqxqq8xtwhw4xwn4qh"); err == nil {
		t.Error("ParseHeader must refuse a non-mt string")
	}
}

func TestDecodeReassemblesAndConfirms(t *testing.T) {
	for _, tc := range []struct {
		name    string
		set     []string
		rawHex  string
		txid    string
		in, out int
	}{
		{"even", even, evenRawHex, evenTxid, 1, 2},
		{"uneven", uneven, "", unevenTxid, 1, 4},
	} {
		tx, err := Decode(tc.set)
		if err != nil {
			t.Fatalf("%s: %v", tc.name, err)
		}
		if tx.TxidDisplay != tc.txid {
			t.Errorf("%s: txid %s, want %s", tc.name, tx.TxidDisplay, tc.txid)
		}
		if tc.rawHex != "" && hex.EncodeToString(tx.Raw) != tc.rawHex {
			t.Errorf("%s: raw bytes diverge", tc.name)
		}
		if tx.Inputs != tc.in || tx.Outputs != tc.out || !tx.SegWit {
			t.Errorf("%s: summary %+v", tc.name, tx)
		}
	}
}

func TestDecodeIsOrderIndependentAndDuplicateTolerant(t *testing.T) {
	shuffled := []string{even[4], even[0], even[5], even[2], even[1], even[3]}
	tx, err := Decode(shuffled)
	if err != nil || tx.TxidDisplay != evenTxid {
		t.Fatalf("shuffled: %v", err)
	}
	dup := append(append([]string{}, even...), even[2], strings.ToUpper(even[3]))
	tx, err = Decode(dup)
	if err != nil || tx.TxidDisplay != evenTxid {
		t.Fatalf("duplicates: %v", err)
	}
}

func TestDecodeRefusesWhatItMust(t *testing.T) {
	// A missing chunk.
	if _, err := Decode(even[:5]); err == nil {
		t.Error("an incomplete set must not decode")
	}
	// A chunk from another set.
	if _, err := Decode(append(append([]string{}, even...), uneven[0])); err == nil {
		t.Error("a mixed set must be refused")
	}
	// A damaged string: NO correction on this side, ever.
	bad := even[0][:len(even[0])-1] + "y"
	if _, err := Decode([]string{bad}); err == nil {
		t.Error("a damaged string must be refused, not corrected")
	}
	if _, err := Decode(nil); err == nil {
		t.Error("empty input must error")
	}
}

// The two arms that make confirmation SEMANTIC rather than structural.
func TestSmuggledEntropyAndForgedSetIdAreRefused(t *testing.T) {
	// 32 bytes of entropy: complete, BCH-valid, reassembles — not a tx.
	if _, err := Decode([]string{smuggled}); err == nil {
		t.Error("wrapped entropy must not confirm")
	}
	// A real transaction under a foreign chunk_set_id: parses — binding fails.
	if _, err := Decode(foreign); err == nil {
		t.Error("a foreign chunk_set_id must fail the txid binding")
	}
}

func TestParseTxMatchesTheNode(t *testing.T) {
	raw, _ := hex.DecodeString(evenRawHex)
	tx, err := ParseTx(raw)
	if err != nil {
		t.Fatal(err)
	}
	if tx.TxidDisplay != evenTxid {
		t.Errorf("txid %s, want %s", tx.TxidDisplay, evenTxid)
	}
	if tx.ChunkSetID() != 0x2dcf2 {
		t.Errorf("ChunkSetID %#x, want 0x2dcf2", tx.ChunkSetID())
	}
	// Refusals: truncations never parse and never panic; trailing bytes refuse.
	for n := range raw {
		if _, err := ParseTx(raw[:n]); err == nil {
			t.Fatalf("prefix of %d bytes accepted", n)
		}
	}
	if _, err := ParseTx(append(append([]byte{}, raw...), 0x00)); err == nil {
		t.Error("trailing bytes must refuse")
	}
	if _, err := ParseTx(make([]byte, 32)); err == nil {
		t.Error("32 zero bytes are not a transaction")
	}
}

// RED FIRST (G-P3.2). The device had NO signature check at all: parseTx called
// skipBytes for the scriptSig and DISCARDED the length. A witness-stripped
// transaction has the same txid as the honest one, so every other check --
// parse, txid derivation, chunk_set_id binding -- passes it.
//
// The host refuses this. Before this test the device would have engraved it.
func TestAStrippedTransactionIsNotSigned(t *testing.T) {
	honest := unhexT(t, "")
	stripped := unhexT(t, "02000000017c8da925af70e49a12b0cea7b639df5037c87b7fa61f262b86ac32c47aa3ba1a0000000000fdffffff02404b4c0000000000160014c1de0dd435d1d4ad97ed1f51d63f91c800cc4eab3ea1b92901000000160014751097c299d6354fbb2c5a84512dd708f2902f5e60000000")

	h, err := ParseTx(honest)
	if err != nil {
		t.Fatalf("honest body must parse: %v", err)
	}
	s, err := ParseTx(stripped)
	if err != nil {
		t.Fatalf("the stripped body still parses -- that is the problem: %v", err)
	}
	if h.TxidDisplay != s.TxidDisplay {
		t.Fatal("premise broken: if the txids differed the txid alone would catch this")
	}
	if !h.EveryInputSigned {
		t.Error("the honest body's input carries a witness")
	}
	if s.EveryInputSigned {
		t.Error("the stripped body has no witness and an empty scriptSig -- unsigned")
	}
}

func unhexT(t *testing.T, s string) []byte {
	t.Helper()
	b := make([]byte, len(s)/2)
	for i := range b {
		var v byte
		for j := 0; j < 2; j++ {
			c := s[i*2+j]
			switch {
			case c >= '0' && c <= '9':
				v = v<<4 | (c - '0')
			case c >= 'a' && c <= 'f':
				v = v<<4 | (c - 'a' + 10)
			default:
				t.Fatalf("bad hex %q", c)
			}
		}
		b[i] = v
	}
	return b
}

// The predicate is PER INPUT. Mutation-tested: replacing the all() with an
// any() over the whole transaction leaves TestAStrippedTransactionIsNotSigned
// GREEN and turns this one RED. The Rust side needed exactly this second vector
// for exactly this reason -- the lesson landed twice.
func TestOneSignedInputDoesNotVouchForTheOthers(t *testing.T) {
	// Input 0 legacy-signed (non-empty scriptSig), input 1 a segwit input whose
	// witness was stripped (empty scriptSig, no witness). Serialized legacy.
	tx, err := ParseTx(unhexT(t, ""))
	if err != nil {
		t.Fatalf("a mixed stripped body parses: %v", err)
	}
	if tx.Inputs != 2 {
		t.Fatalf("want 2 inputs, got %d", tx.Inputs)
	}
	if tx.EveryInputSigned {
		t.Error("input 1 has no scriptSig and no witness -- input 0 being signed " +
			"does not make the transaction spendable")
	}
}
